  if(sample?.width!==expectedWidth||sample?.height!==expectedHeight)errors.push(`drawing-buffer dimensions ${sample?.width}x${sample?.height} != ${expectedWidth}x${expectedHeight}`);
  if(sample?.canvasWidth!==expectedWidth||sample?.canvasHeight!==expectedHeight)errors.push(`canvas dimensions ${sample?.canvasWidth}x${sample?.canvasHeight} != ${expectedWidth}x${expectedHeight}`);
  if(sample?.sampledPixels!==expectedPixels||sample?.sampledPixels!==sample?.width*sample?.height)errors.push(`sampledPixels ${sample?.sampledPixels} != ${expectedPixels}`);
