  if(sample?.opaquePixels!==sample?.sampledPixels)errors.push(`opaquePixels ${sample?.opaquePixels} != sampledPixels ${sample?.sampledPixels}`);
  if(!Number.isInteger(sample?.backgroundPixels)||sample.backgroundPixels<0)errors.push(`backgroundPixels ${sample?.backgroundPixels} must be a non-negative integer`);
  if(!Number.isInteger(sample?.nonBackground)||sample.nonBackground<0)errors.push(`nonBackground ${sample?.nonBackground} must be a non-negative integer`);
  if(sample?.backgroundPixels+sample?.nonBackground!==sample?.sampledPixels)errors.push(`background/nonBackground partition ${sample?.backgroundPixels}+${sample?.nonBackground} != ${sample?.sampledPixels}`);
